/* PWADC Security Operations Suite v3.3.1.0 | module: training-uniforms */
function renderTrainingPage(){
  const topics=activeTrainingTopics().slice().sort((a,b)=>String(a.name||'').localeCompare(String(b.name||'')));
  const rows=trainingRows();
  const visibleRows=filteredTrainingRows(rows);
  const expired=visibleRows.filter(r=>r.status==='Expired'||r.status==='Overdue').length;
  const expiring=visibleRows.filter(r=>r.status==='Expiring Soon'||r.status==='Due Soon').length;
  const missing=visibleRows.filter(r=>r.status==='Missing'||r.status==='No Record').length;
  const current=visibleRows.filter(r=>r.status==='Current'||r.status==='Complete').length;
  const optionalRecorded=visibleRows.filter(r=>!r.applies&&r.rec).length;
  const postMetrics=postReadinessSummaryMetrics();
  return `<div class="training-hero"><div><div class="page-title">Training Tracker</div><div class="page-sub">Standalone training page for required training, optional training, expiration tracking, trainers, and post-readiness exceptions.</div></div><div class="training-quick-actions"><button onclick="openTrainingTopicModal()">+ Add Topic</button><button class="gold" onclick="openTrainingRecordModal()">+ Add Training Record</button><button onclick="printTrainingMatrix()">Print Training</button><button onclick="exportTrainingCSV()">Export CSV</button></div></div>
  ${screenGuide('training')}${renderPeopleWorkflowNav('training')}<div class="notice"><strong>Optional training is allowed:</strong> Add training for any employee/topic cell, even when that topic is not required. Optional recorded training is shown as its own blue/current-style record instead of being buried under Not Required.</div>
  <div class="training-readiness-grid"><div class="kpi"><div class="num">${topics.length}</div><div class="lbl">Active Topics</div></div><div class="kpi"><div class="num">${roster.trainingRecords.length}</div><div class="lbl">Records</div></div><div class="kpi"><div class="num ok">${current}</div><div class="lbl">Current</div></div><div class="kpi"><div class="num schedule-risk">${expired}</div><div class="lbl">Expired</div></div><div class="kpi"><div class="num">${expiring}</div><div class="lbl">Expiring Soon</div></div><div class="kpi"><div class="num schedule-risk">${missing}</div><div class="lbl">Missing</div></div><div class="kpi"><div class="num ok">${optionalRecorded}</div><div class="lbl">Optional Recorded</div></div><div class="kpi"><div class="num schedule-risk">${postMetrics.notReady}</div><div class="lbl">Not Post-Ready</div></div></div>
  <div class="training-command-row"><div class="training-command-card"><strong>Quick Add</strong><span>Add required or optional training for any employee.</span><button class="gold" onclick="openTrainingRecordModal()">Add Training</button></div><div class="training-command-card"><strong>Review Exceptions</strong><span>Filter to missing, expired, expiring, or post-readiness issues.</span><button onclick="window._trainingPostReadyFilter='issues';safeRenderPages()">Show Issues</button></div><div class="training-command-card"><strong>Employee Packet</strong><span>Use each employee card to print a focused training record.</span><button onclick="printTrainingMatrix()">Print Matrix</button></div></div>
  <div class="training-filters"><div><label>Search</label><input id="trainingSearch" placeholder="Employee, topic, trainer, notes..." value="${esc(window._trainingSearch||'')}" oninput="window._trainingSearch=this.value;safeRenderPages()"></div><div><label>Topic</label><select id="trainingTopicFilter" onchange="window._trainingTopicFilter=this.value;safeRenderPages()"><option value="">All Topics</option>${topics.map(t=>`<option value="${esc(t.id)}" ${(window._trainingTopicFilter||'')==String(t.id)?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div><div><label>Status</label><select id="trainingStatusFilter" onchange="window._trainingStatusFilter=this.value;safeRenderPages()"><option value="">All Statuses</option>${['Current','Expiring Soon','Expired','Missing','Not Required'].map(x=>`<option value="${x}" ${(window._trainingStatusFilter||'')===x?'selected':''}>${x}</option>`).join('')}</select></div><div><label>Requirement</label><select id="trainingReqFilter" onchange="window._trainingReqFilter=this.value;safeRenderPages()"><option value="">All Requirements</option>${['All','Supervisors','Leads','Gate','BaseEOC','DockCrosswalk','Reception','PLE','Custom'].map(x=>`<option value="${x}" ${(window._trainingReqFilter||'')===x?'selected':''}>${esc(trainingRequirementLabel(x))}</option>`).join('')}</select></div><div><label>Post Readiness</label><select id="trainingPostReadyFilter" onchange="window._trainingPostReadyFilter=this.value;safeRenderPages()"><option value="">All</option><option value="issues" ${(window._trainingPostReadyFilter||'')==='issues'?'selected':''}>Employees with readiness issues</option>${trainingPostGroups().map(g=>`<option value="${g.key}" ${(window._trainingPostReadyFilter||'')===g.key?'selected':''}>${esc(g.label)}</option>`).join('')}</select></div><div style="align-self:end"><button onclick="window._trainingSearch='';window._trainingTopicFilter='';window._trainingStatusFilter='';window._trainingReqFilter='';window._trainingPostReadyFilter='';safeRenderPages()">Clear Filters</button></div></div>
  <div class="training-layout-polished"><div class="card training-side-card"><div class="card-title">Training Topics</div>${renderTrainingTopicsList()}<div class="card-title" style="margin-top:14px">Post Readiness</div>${renderPostReadinessSummary()}</div><div class="training-main-grid"><div class="card"><div class="card-title">Employee Training Tables</div><div class="training-section-note">Grouped by employee and shift. Each cell can be added or edited, including optional/not-required training.</div><div class="training-print-note">Status summary: ${expired} expired · ${expiring} expiring soon · ${missing} missing · ${optionalRecorded} optional record(s) · ${postMetrics.notReady} employee(s) not post-ready.</div></div>${renderTrainingMatrix()}</div></div>`
}
function trainingRows(){const topics=activeTrainingTopics().slice().sort((a,b)=>String(a.name||'').localeCompare(String(b.name||'')));const emps=(roster.employees||[]).filter(e=>!isArchivedEmployee(e)).slice().sort((a,b)=>fullName(a).localeCompare(fullName(b)));let rows=[];for(const emp of emps){for(const topic of topics){const rec=latestTrainingRecord(emp.id,topic.id);const applies=topicAppliesToEmployee(topic,emp);const status=applies?trainingStatus(rec,topic):(rec?trainingStatus(rec,topic):'Not Required');rows.push({emp,topic,rec,status,applies});}}return rows}
function filteredTrainingRows(rows){const q=(window._trainingSearch||'').toLowerCase();const topicFilter=String(window._trainingTopicFilter||'');const statusFilter=window._trainingStatusFilter||'';const reqFilter=window._trainingReqFilter||'';const postReadyFilter=window._trainingPostReadyFilter||'';return rows.filter(r=>!topicFilter||String(r.topic.id)===topicFilter).filter(r=>!statusFilter||r.status===statusFilter).filter(r=>!reqFilter||String(r.topic.requirementGroup||'All')===reqFilter).filter(r=>!q||(fullName(r.emp)+' '+(r.emp.eid||'')+' '+(r.emp.shift||'')+' '+(r.topic.name||'')+' '+(r.topic.notes||'')+' '+((r.rec&&r.rec.notes)||'')+' '+((r.rec&&r.rec.trainer)||'')).toLowerCase().includes(q))}
function renderTrainingTopicsList(){const topics=(roster.trainingTopics||[]).slice().sort((a,b)=>String(a.name||'').localeCompare(String(b.name||'')));if(!topics.length)return '<div class="training-empty">No topics yet. Add a topic to start tracking training.</div>';return topics.map(t=>`<div class="topic-card"><div><div class="topic-title">${esc(t.name)} ${t.active===false?'<span class="training-status training-na">Inactive</span>':''}</div><div class="topic-meta">${t.required!==false?'Required':'Optional'} · ${esc(intervalLabel(t.intervalDays))} · Warn ${Number(t.warningDays||30)} day(s)<br><span class="training-topic-scope">${esc(trainingRequirementLabel(t.requirementGroup||'All'))}</span>${t.requirementText?'<div class="training-req-note">Match: '+esc(t.requirementText)+'</div>':''}${t.notes?'<br>'+esc(t.notes):''}</div></div><div class="td-actions"><button class="sm" onclick="openTrainingTopicModal('${esc(t.id)}')">Edit</button><button class="sm danger" onclick="deleteTrainingTopic('${esc(t.id)}')">Remove</button></div></div>`).join('')}
function renderPostReadinessSummary(){const active=(roster.employees||[]).filter(e=>!isArchivedEmployee(e));return trainingPostGroups().map(g=>{let ready=0,issues=0,notReq=0;for(const e of active){const r=postReadinessForEmployee(e,g.key);if(r.status==='Not Required')notReq++;else if(r.status==='Ready')ready++;else issues++;}return `<div class="topic-card"><div><div class="topic-title">${esc(g.label)}</div><div class="topic-meta">Ready: ${ready} · Issues: ${issues} · Not required: ${notReq}</div></div><div>${issues?'<span class="risk-chip bad">Review</span>':'<span class="risk-chip ok">OK</span>'}</div></div>`}).join('')}

function renderTrainingMatrix(){let topics=activeTrainingTopics().slice().sort((a,b)=>String(a.name||'').localeCompare(String(b.name||'')));let emps=(roster.employees||[]).filter(e=>!isArchivedEmployee(e)).slice().sort((a,b)=>{const sa=shiftSortName(a.shift),sb=shiftSortName(b.shift);return sa.localeCompare(sb)||fullName(a).localeCompare(fullName(b));});const q=(window._trainingSearch||'').toLowerCase();const topicFilter=String(window._trainingTopicFilter||'');const statusFilter=window._trainingStatusFilter||'';const reqFilter=window._trainingReqFilter||'';const postReadyFilter=window._trainingPostReadyFilter||'';if(topicFilter)topics=topics.filter(t=>String(t.id)===topicFilter);if(reqFilter)topics=topics.filter(t=>String(t.requirementGroup||'All')===reqFilter);if(q){emps=emps.filter(emp=>{const empHit=(fullName(emp)+' '+(emp.eid||'')+' '+(emp.shift||'')+' '+employeeTrainingBlob(emp)).toLowerCase().includes(q);const trainHit=topics.some(topic=>{const rec=latestTrainingRecord(emp.id,topic.id);return ((topic.name||'')+' '+(topic.notes||'')+' '+((rec&&rec.notes)||'')+' '+((rec&&rec.trainer)||'')).toLowerCase().includes(q)});return empHit||trainHit;});}if(statusFilter){emps=emps.filter(emp=>topics.some(topic=>{const rec=latestTrainingRecord(emp.id,topic.id);const applies=topicAppliesToEmployee(topic,emp);const st=applies?trainingStatus(rec,topic):(rec?trainingStatus(rec,topic):'Not Required');return st===statusFilter;}));}if(postReadyFilter==='issues'){emps=emps.filter(employeeNotPostReady);}else if(postReadyFilter){emps=emps.filter(emp=>postReadinessForEmployee(emp,postReadyFilter).status!=='Not Required');}if(window._trainingEmployeeFocus){const focus=String(window._trainingEmployeeFocus);const focused=emps.filter(e=>String(e.id)===focus);if(focused.length)emps=focused.concat(emps.filter(e=>String(e.id)!==focus));}if(!topics.length)return '<div class="training-empty">No training topics match the current filter.</div>';if(!emps.length)return '<div class="training-empty">No employees match the current training filters.</div>';const groups={};for(const emp of emps){const key=trainingShiftGroup(emp.shift);groups[key]=groups[key]||[];groups[key].push(emp);}const order=['1st','2nd','3rd','GATE','W/E Gate','DOCK','Crosswalk','RECP','Other'];const keys=Object.keys(groups).sort((a,b)=>(order.indexOf(a)<0?99:order.indexOf(a))-(order.indexOf(b)<0?99:order.indexOf(b))||a.localeCompare(b));return keys.map(key=>`<div class="training-shift-block"><div class="training-shift-head"><span>${esc(trainingShiftLabel(key))}</span><small>${groups[key].length} employee(s)</small></div>${groups[key].map(emp=>{const focused=String(window._trainingEmployeeFocus||'')===String(emp.id||'');return `<div class="training-employee-card ${focused?'focused':''}" id="trainingEmp_${String(emp.id||'').replace(/[^a-zA-Z0-9_-]/g,'')}"><div class="training-employee-head"><div><div class="training-employee-name">${esc(fullName(emp))}</div><div class="training-employee-meta">${esc(emp.shift||'')} ${emp.eid?'· '+esc(emp.eid):''}</div><div style="margin-top:5px">${employeePostReadiness(emp).filter(p=>p.status!=='Not Required').slice(0,4).map(p=>`<span class="risk-chip ${p.status==='Ready'?'ok':(p.status==='Expiring Soon'?'warn':'bad')}">${esc(p.label.replace(' Ready',''))}: ${esc(p.status)}</span>`).join('')}</div></div><div class="training-employee-print"><button class="sm gold" onclick="openTrainingRecordModal('', '${esc(emp.id)}', '')">+ Add Training</button><button class="sm" onclick="printEmployeeTraining('${esc(emp.id)}')">Print Employee</button></div></div><div class="training-matrix-wrap polished"><table class="training-matrix polished"><thead><tr>${topics.map(t=>`<th class="training-topic-th">${esc(t.name)}<div class="training-topic-subline">${t.required!==false?'Required':'Optional'} · ${esc(intervalLabel(t.intervalDays))}<br>${esc(trainingRequirementLabel(t.requirementGroup||'All'))}</div></th>`).join('')}</tr></thead><tbody><tr>${topics.map(topic=>renderTrainingCell(emp,topic,statusFilter)).join('')}</tr></tbody></table></div></div>`}).join('')}</div>`).join('')}
function trainingShiftGroup(shift){const s=String(shift||'').trim();if(/^1st/i.test(s))return '1st';if(/^2nd/i.test(s))return '2nd';if(/^3rd/i.test(s))return '3rd';if(/w\/e gate/i.test(s))return 'W/E Gate';if(/gate/i.test(s))return 'GATE';if(/dock/i.test(s))return 'DOCK';if(/crosswalk/i.test(s))return 'Crosswalk';if(/recp|reception/i.test(s))return 'RECP';return s||'Other'}
function shiftSortName(shift){const order={'1st':'01','2nd':'02','3rd':'03','GATE':'04','W/E Gate':'05','DOCK':'06','Crosswalk':'07','RECP':'08','Other':'99'};const g=trainingShiftGroup(shift);return (order[g]||'98')+' '+g}
function trainingShiftLabel(key){return key==='RECP'?'Reception':key==='GATE'?'Gate':key==='DOCK'?'Dock':key}
function trainingRequirementLabel(group){return ({All:'All employees',Supervisors:'Supervisors',Leads:'Leads / LSO',Gate:'Gate',BaseEOC:'Base / EOC',DockCrosswalk:'Dock / Crosswalk',Reception:'Reception',PLE:'Forklift / PLE',Custom:'Custom match'})[group]||'All employees'}
function employeeTrainingBlob(emp){const schedule=(roster.schedule||[]).filter(row=>(row.days||[]).some(cell=>scheduleNameMatchesEmployee(cell,emp))).map(row=>[row.section,row.post,row.shiftLabel,row.notes].join(' ')).join(' ');return [fullName(emp),emp.eid,emp.rank,emp.title,emp.shift,emp.gateShift,emp.section,emp.type,schedule].filter(Boolean).join(' ').toLowerCase();}
function topicAppliesToEmployee(topic,emp){if(!topic||topic.active===false||!emp||isArchivedEmployee(emp))return false;const group=topic.requirementGroup||'All';const blob=employeeTrainingBlob(emp);if(group==='All')return true;if(group==='Supervisors')return /supervisor|supv|mgr|manager/.test(blob);if(group==='Leads')return /lead|lso/.test(blob);if(group==='Gate')return /gate|0400|1200|2000/.test(blob);if(group==='BaseEOC')return /base|eoc|soc|camera|access|amag|wave/.test(blob);if(group==='DockCrosswalk')return /dock|crosswalk|grocery|perishable|truck/.test(blob);if(group==='Reception')return /reception|recp/.test(blob);if(group==='PLE')return /forklift|ple|powered|lift|cert/.test(blob);if(group==='Custom'){const tokens=String(topic.requirementText||'').toLowerCase().split(',').map(x=>x.trim()).filter(Boolean);return tokens.length?tokens.some(t=>blob.includes(t)):true;}return true}
function requiredTrainingTopicsForEmployee(emp){return (roster.trainingTopics||[]).filter(t=>t.active!==false&&t.required!==false&&topicAppliesToEmployee(t,emp))}
function activeTrainingTopics(){return (roster.trainingTopics||[]).filter(t=>t.active!==false)}
function trainingReadinessForEmployee(emp){const topics=requiredTrainingTopicsForEmployee(emp);let current=0,expiring=0,expired=0,missing=0;const rows=[];for(const t of topics){const rec=latestTrainingRecord(emp.id,t.id);const status=trainingStatus(rec,t);if(status==='Current'||status==='Complete')current++;else if(status==='Expiring Soon'||status==='Due Soon')expiring++;else if(status==='Expired'||status==='Overdue')expired++;else missing++;rows.push({topic:t,status,rec,due:rec&&rec.due||'',completed:rec&&rec.completed||'',trainer:rec&&rec.trainer||''});}const total=topics.length;const good=current;const score=total?Math.round((good/total)*100):100;return{total,current,expiring,expired,missing,score,rows}}
function trainingPostGroups(){return[
  {key:'Gate',label:'Gate Ready'},
  {key:'BaseEOC',label:'Base / EOC Ready'},
  {key:'DockCrosswalk',label:'Dock / Crosswalk Ready'},
  {key:'Supervisors',label:'Supervisor Ready'},
  {key:'PLE',label:'Forklift / PLE Ready'}
]}
function postReadinessForEmployee(emp,group){const topics=activeTrainingTopics().filter(t=>t.required!==false&&t.active!==false&&String(t.requirementGroup||'All')===String(group)&&topicAppliesToEmployee(t,emp));if(!topics.length)return{group,status:'Not Required',total:0,issues:0,rows:[]};let expired=0,missing=0,expiring=0,current=0;const rows=[];for(const t of topics){const rec=latestTrainingRecord(emp.id,t.id);const status=trainingStatus(rec,t);if(status==='Expired'||status==='Overdue')expired++;else if(status==='Missing'||status==='No Record')missing++;else if(status==='Expiring Soon'||status==='Due Soon')expiring++;else current++;rows.push({topic:t,rec,status});}let status='Ready';if(missing)status='Missing Training';else if(expired)status='Expired Training';else if(expiring)status='Expiring Soon';return{group,status,total:topics.length,issues:missing+expired+expiring,current,missing,expired,expiring,rows}}
function employeePostReadiness(emp){return trainingPostGroups().map(g=>({...g,...postReadinessForEmployee(emp,g.key)}))}
function postReadinessBadge(status){let cls=status==='Ready'?'ok':(status==='Not Required'?'':'warn');if(status==='Missing Training'||status==='Expired Training')cls='bad';return `<span class="risk-chip ${cls}">${esc(status)}</span>`}
function employeeNotPostReady(emp){return employeePostReadiness(emp).some(r=>r.status==='Missing Training'||r.status==='Expired Training'||r.status==='Expiring Soon')}
function postReadinessSummaryMetrics(emps=(roster.employees||[]).filter(e=>!isArchivedEmployee(e))){let notReady=0,missing=0,expired=0,expiring=0,ready=0,required=0;for(const e of emps){let hasIssue=false;for(const r of employeePostReadiness(e)){if(r.status==='Not Required')continue;required++;if(r.status==='Ready')ready++;else{hasIssue=true;if(r.status==='Missing Training')missing++;else if(r.status==='Expired Training')expired++;else if(r.status==='Expiring Soon')expiring++;}}if(hasIssue)notReady++;}return{notReady,missing,expired,expiring,ready,required}}

function trainingStatusIssue(status){return ['Missing','No Record','Expired','Overdue','Expiring Soon','Due Soon'].includes(status)}
function renderTrainingCell(emp,topic,statusFilter=''){const rec=latestTrainingRecord(emp.id,topic.id);const applies=topicAppliesToEmployee(topic,emp);const status=applies?trainingStatus(rec,topic):(rec?trainingStatus(rec,topic):'Not Required');const filteredClass=statusFilter&&status!==statusFilter?' training-filtered-out':'';const optionalRecorded=!applies&&!!rec;const reqTag=`<span class="training-required-tag ${applies?'required':'optional'}">${applies?'Required':'Optional'}</span>`;const dates=rec?`<div class="training-dates">${!applies?'Optional / not required for this employee.<br>':''}Completed: ${esc(fmtDate(rec.completed||''))}<br>Expires: ${esc(fmtDate(rec.due||''))}${rec.trainer?'<br>Trainer: '+esc(rec.trainer):''}${rec.notes?'<br>Notes: '+esc(rec.notes):''}</div>`:(!applies?`<div class="training-dates">Not required, but optional training can be added.</div>`:'<div class="training-dates">No completion recorded</div>');return `<td class="training-cell${filteredClass}${!applies?' not-required':''}${optionalRecorded?' optional-recorded':''}"><div class="training-cell-inner">${reqTag}${trainingStatusBadge(status)}${dates}<div class="training-actions"><button class="sm" onclick="openTrainingRecordModal('${rec?esc(rec.id):''}','${esc(emp.id)}','${esc(topic.id)}')">${rec?'Edit':'Add'}</button>${rec?`<button class="sm danger" onclick="deleteTrainingRecord('${esc(rec.id)}')">Remove</button>`:''}</div></div></td>`}

function latestTrainingRecord(empId,topicId){return (roster.trainingRecords||[]).filter(r=>String(r.employeeId)===String(empId)&&String(r.topicId)===String(topicId)).sort((a,b)=>String(b.completed||'').localeCompare(String(a.completed||'')))[0]||null}
function trainingStatus(rec,topic){if(!rec)return 'Missing';if(!rec.due||!topic||!Number(topic.intervalDays))return 'Current';const today=parseISO(new Date().toISOString().slice(0,10));const due=parseISO(rec.due);const diff=Math.ceil((due-today)/86400000);if(diff<0)return 'Expired';if(diff<=Number(topic.warningDays||30))return 'Expiring Soon';return 'Current'}
function trainingStatusBadge(status){const cls=(status==='Current'||status==='Complete')?'training-current':(status==='Expiring Soon'||status==='Due Soon')?'training-expiring':(status==='Expired'||status==='Overdue')?'training-expired':status==='Not Required'?'training-na':'training-missing';return `<span class="training-status ${cls}">${esc(status)}</span>`}
function intervalLabel(n){n=Number(n)||0;if(!n)return 'No expiration';if(n===30)return '30 days';if(n===90)return '90 days';if(n===180)return '6 months';if(n===365)return 'Annual';if(n===730)return 'Every 2 years';return n+' days'}
function trainingTopicById(id){return (roster.trainingTopics||[]).find(t=>String(t.id)===String(id))}
function trainingRecordById(id){return (roster.trainingRecords||[]).find(r=>String(r.id)===String(id))}
function openTrainingTopicModal(id=''){const t=id?trainingTopicById(id):null;const group=t&&t.requirementGroup||'All';showModal(`<div class="modal-head"><div class="modal-title">${t?'Edit Training Topic':'Add Training Topic'}</div><button onclick="closeModal()">Close</button></div><div class="form-grid"><div class="full"><label>Topic Name</label><input id="trainTopicName" value="${esc(t&&t.name||'')}" placeholder="Gate Post Training, Emergency Procedures"></div><div><label>Expiration Days</label><input id="trainTopicInterval" type="number" min="0" value="${esc(t&&Number(t.intervalDays)||365)}"><div class="settings-help">Use 0 for no expiration, 365 for annual.</div></div><div><label>Warning Window Days</label><input id="trainTopicWarning" type="number" min="1" value="${esc(t&&Number(t.warningDays)||30)}"><div class="settings-help">Status changes to Expiring Soon inside this window.</div></div><div><label>Required?</label><select id="trainTopicRequired"><option value="yes" ${!t||t.required!==false?'selected':''}>Yes</option><option value="no" ${t&&t.required===false?'selected':''}>No</option></select></div><div><label>Active?</label><select id="trainTopicActive"><option value="yes" ${!t||t.active!==false?'selected':''}>Active</option><option value="no" ${t&&t.active===false?'selected':''}>Inactive</option></select></div><div><label>Required For</label><select id="trainTopicGroup" onchange="document.getElementById('trainTopicCustomWrap').style.display=this.value==='Custom'?'block':'none'">${['All','Supervisors','Leads','Gate','BaseEOC','DockCrosswalk','Reception','PLE','Custom'].map(x=>`<option value="${x}" ${group===x?'selected':''}>${esc(trainingRequirementLabel(x))}</option>`).join('')}</select></div><div id="trainTopicCustomWrap" class="full" style="display:${group==='Custom'?'block':'none'}"><label>Custom Match Words</label><input id="trainTopicRequirementText" value="${esc(t&&t.requirementText||'')}" placeholder="Comma-separated words to match employee/schedule, e.g. camera, freezer"><div class="settings-help">Custom topics apply when any word matches the employee's shift, rank, or scheduled post.</div></div><div class="full"><label>Notes</label><input id="trainTopicNotes" value="${esc(t&&t.notes||'')}" placeholder="Optional standard, policy reference, or reminder note"></div></div><div class="modal-actions"><button onclick="closeModal()">Cancel</button><button class="primary" onclick="saveTrainingTopic('${esc(id)}')">Save Topic</button></div>`)}
function saveTrainingTopic(id=''){const name=val('trainTopicName').trim();if(!name){toast('Training topic name is required');return;}if((roster.trainingTopics||[]).some(t=>String(t.id)!==String(id)&&String(t.name||'').toLowerCase()===name.toLowerCase())){toast('That topic already exists');return;}const intervalDays=Math.max(0,Number(val('trainTopicInterval'))||0);const warningDays=Math.max(1,Number(val('trainTopicWarning'))||30);const data={name,intervalDays,warningDays,required:val('trainTopicRequired')!=='no',active:val('trainTopicActive')!=='no',requirementGroup:val('trainTopicGroup')||'All',requirementText:val('trainTopicRequirementText').trim(),notes:val('trainTopicNotes').trim()};if(id){Object.assign(trainingTopicById(id),data);}else{roster.trainingTopics.push({id:roster.nextTrainingTopicId++, ...data});}saveRosterNow('training-topic').then(ok=>{if(ok){closeModal();safeRenderPages();toast('Training topic saved')}})}
function deleteTrainingTopic(id){const t=trainingTopicById(id);if(!t)return;const count=(roster.trainingRecords||[]).filter(r=>String(r.topicId)===String(id)).length;if(!confirm('Remove training topic "'+t.name+'"?'+(count?'\n\nThis will also remove '+count+' record(s).':'')))return;roster.trainingTopics=roster.trainingTopics.filter(x=>String(x.id)!==String(id));roster.trainingRecords=roster.trainingRecords.filter(r=>String(r.topicId)!==String(id));saveRoster('training-topic-remove');safeRenderPages();toast('Training topic removed')}
function openTrainingRecordModal(recordId='',empId='',topicId=''){const rec=recordId?trainingRecordById(recordId):null;const emps=(roster.employees||[]).filter(e=>!isArchivedEmployee(e)).slice().sort((a,b)=>fullName(a).localeCompare(fullName(b)));const topics=activeTrainingTopics().slice().sort((a,b)=>String(a.name||'').localeCompare(String(b.name||'')));if(!emps.length){toast('Add employees before adding training records');return;}if(!topics.length){toast('Add a topic before adding records');return;}const selEmp=rec?rec.employeeId:(empId||emps[0].id);const selTopic=rec?rec.topicId:(topicId||topics[0].id);showModal(`<div class="modal-head"><div class="modal-title">${rec?'Edit Training Record':'Add Training Record'}</div><button onclick="closeModal()">Close</button></div><div class="form-grid"><div class="full"><label>Employee</label><select id="trainRecEmp">${emps.map(e=>`<option value="${esc(e.id)}" ${String(selEmp)===String(e.id)?'selected':''}>${esc(fullName(e))}</option>`).join('')}</select></div><div class="full"><label>Topic</label><select id="trainRecTopic" onchange="trainingRecordDateChanged()">${topics.map(t=>`<option value="${esc(t.id)}" ${String(selTopic)===String(t.id)?'selected':''}>${esc(t.name)} · ${esc(trainingRequirementLabel(t.requirementGroup||'All'))}</option>`).join('')}</select></div><div><label>Completed Date</label><input id="trainRecCompleted" type="date" value="${esc(rec&&rec.completed||new Date().toISOString().slice(0,10))}" onchange="trainingRecordDateChanged()"></div><div><label>Expiration Date</label><input id="trainRecDue" type="date" value="${esc(rec&&rec.due||'')}"></div><div><label>Trainer</label><input id="trainRecTrainer" value="${esc(rec&&rec.trainer||currentUserName())}" placeholder="Trainer / supervisor"></div><div class="full"><label>Notes</label><input id="trainRecNotes" value="${esc(rec&&rec.notes||'')}" placeholder="Optional notes"></div></div><div class="modal-actions"><button onclick="closeModal()">Cancel</button><button class="primary" onclick="saveTrainingRecord('${esc(recordId)}')">Save Record</button></div>`);setTimeout(trainingRecordDateChanged,0)}
function trainingRecordDateChanged(){const completed=val('trainRecCompleted');const topic=trainingTopicById(val('trainRecTopic'));const due=document.getElementById('trainRecDue');if(due&&completed&&topic&&Number(topic.intervalDays))due.value=addDays(completed,Number(topic.intervalDays));if(due&&completed&&topic&&!Number(topic.intervalDays))due.value=''}
function saveTrainingRecord(recordId=''){const employeeId=val('trainRecEmp'),topicId=val('trainRecTopic'),completed=val('trainRecCompleted'),due=val('trainRecDue'),trainer=val('trainRecTrainer').trim(),notes=val('trainRecNotes').trim();if(!employeeId||!topicId||!completed){toast('Employee, topic, and completed date are required');return;}const data={employeeId,topicId,completed,due,trainer,notes};if(recordId){Object.assign(trainingRecordById(recordId),data);}else{roster.trainingRecords.push({id:roster.nextTrainingRecordId++, ...data});}saveRosterNow('training-record').then(ok=>{if(ok){closeModal();safeRenderPages();toast('Training record saved')}})}
function deleteTrainingRecord(id){if(!confirm('Remove this training record?'))return;roster.trainingRecords=roster.trainingRecords.filter(r=>String(r.id)!==String(id));saveRoster('training-record-remove');safeRenderPages();toast('Training record removed')}
function printEmployeeTraining(empId){const emp=rosterEmployeeById(empId);if(!emp){toast('Employee not found');return;}const topics=activeTrainingTopics().slice().sort((a,b)=>String(a.name||'').localeCompare(String(b.name||'')));const readiness=trainingReadinessForEmployee(emp);const post=employeePostReadiness(emp);const rows=topics.map(topic=>{const rec=latestTrainingRecord(emp.id,topic.id);const applies=topicAppliesToEmployee(topic,emp);const st=applies?trainingStatus(rec,topic):(rec?trainingStatus(rec,topic):'Not Required');return `<tr><td>${esc(topic.name||'')}</td><td>${applies?'Required':'Optional / Not Required'}</td><td>${esc(st)}</td><td>${esc(fmtDate(rec&&rec.completed||''))}</td><td>${esc(fmtDate(rec&&rec.due||''))}</td><td>${esc(rec&&rec.trainer||'')}</td><td>${esc(rec&&rec.notes||'')}</td></tr>`}).join('');const body=`<div class="report-section"><div class="report-summary"><strong>${esc(fullName(emp))}</strong><br>${esc(emp.shift||'')} ${emp.eid?'· '+esc(emp.eid):''}<br>Readiness score: ${readiness.score}% · Current: ${readiness.current} · Missing: ${readiness.missing} · Expired: ${readiness.expired} · Expiring: ${readiness.expiring}</div></div><div class="report-section"><h2>Post Readiness</h2><table class="report-table"><thead><tr><th>Post Area</th><th>Status</th><th>Issues</th></tr></thead><tbody>${post.map(p=>`<tr><td>${esc(p.label)}</td><td>${esc(p.status)}</td><td>${esc(Number(p.issues||0))}</td></tr>`).join('')}</tbody></table></div><div class="report-section"><h2>Training Records</h2><table class="report-table"><thead><tr><th>Topic</th><th>Requirement</th><th>Status</th><th>Completed</th><th>Expires</th><th>Trainer</th><th>Notes</th></tr></thead><tbody>${rows}</tbody></table></div>`;openReportWindow(reportDoc('Employee Training Packet','Required and optional training record for one employee.',body,'landscape'),false)}
function exportTrainingCSV(){const topics=activeTrainingTopics().slice().sort((a,b)=>String(a.name||'').localeCompare(String(b.name||'')));let rows=[['Employee','EID','Shift','Topic','Required For','Status','Completed','Expires','Trainer','Notes']];for(const emp of (roster.employees||[]).filter(e=>!isArchivedEmployee(e)).slice().sort((a,b)=>fullName(a).localeCompare(fullName(b)))){for(const topic of topics){const rec=latestTrainingRecord(emp.id,topic.id);const applies=topicAppliesToEmployee(topic,emp);rows.push([fullName(emp),emp.eid||'',emp.shift||'',topic.name||'',trainingRequirementLabel(topic.requirementGroup||'All'),applies?trainingStatus(rec,topic):(rec?trainingStatus(rec,topic):'Not Required'),rec&&rec.completed||'',rec&&rec.due||'',rec&&rec.trainer||'',rec&&rec.notes||'']);}}downloadCSV('PWADC_Training_'+new Date().toISOString().slice(0,10)+'.csv',rows);toast('Exported training CSV')}
function printTrainingMatrix(){const topics=activeTrainingTopics().slice().sort((a,b)=>String(a.name||'').localeCompare(String(b.name||'')));const emps=(roster.employees||[]).filter(e=>!isArchivedEmployee(e)).slice().sort((a,b)=>fullName(a).localeCompare(fullName(b)));let html=`<div class="print-overlay" id="printOverlay"><div class="print-toolbar"><div><h2>PWADC Security Training Matrix</h2><div>${new Date().toLocaleString()} · ${topics.length} active topic(s) · ${roster.trainingRecords.length} record(s)</div></div><div><button onclick="window.print()">Print</button> <button onclick="document.getElementById('printOverlay').remove()">Close</button></div></div><table class="print-table"><thead><tr><th>Employee</th>${topics.map(t=>`<th>${esc(t.name)}<br><small>${esc(trainingRequirementLabel(t.requirementGroup||'All'))}</small></th>`).join('')}</tr></thead><tbody>${emps.map(emp=>`<tr><td>${esc(fullName(emp))}<br>${esc(emp.shift||'')}</td>${topics.map(topic=>{const rec=latestTrainingRecord(emp.id,topic.id);const applies=topicAppliesToEmployee(topic,emp);return `<td>${esc(applies?trainingStatus(rec,topic):(rec?trainingStatus(rec,topic):'Not Required'))}<br>${rec?('Completed: '+esc(fmtDate(rec.completed||''))+'<br>Expires: '+esc(fmtDate(rec.due||''))+'<br>Trainer: '+esc(rec.trainer||'')):(applies?'No record':'Optional / not required')}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>`;document.body.insertAdjacentHTML('beforeend',html);setTimeout(()=>window.print(),150)}

const DEFAULT_EQUIPMENT_TYPES=['Shirt','Pants','Jacket','Safety Vest','Other'];
const NON_UNIFORM_ITEM_TYPES=['Badge','Radio','Keys','Access Card','Flashlight','Rain Gear'];
function isUniformItemType(item){const x=String(item||'').trim().toLowerCase();return !NON_UNIFORM_ITEM_TYPES.some(n=>n.toLowerCase()===x);}
const EQUIPMENT_STATUS=['Needed','Ordered','Issued','Returned','Lost','Damaged','Retired'];
function titleCase(v){return String(v||'').replace(/[-_]/g,' ').replace(/\b\w/g,c=>c.toUpperCase())}
function normalizedStatus(v){let s=String(v||'needed').trim().toLowerCase();if(s==='')s='needed';return s.replace(/\s+/g,'-')}
function uniformQty(e,k){if(k==='jacket')return 1;let cls=employmentClass(e);return cls==='PT'?3:5}
function equipmentList(e){e.equipmentItems=Array.isArray(e.equipmentItems)?e.equipmentItems:[];return e.equipmentItems}
function getUniformItemsForEmployee(e){let out=[];if(!e)return out;for(const k of ['shirt','pants','jacket']){let status=normalizedStatus(e[k+'Status']||'needed');let qty=uniformQty(e,k);out.push({employee:fullName(e),employeeId:e.id,rank:e.rank||'',shift:e.shift||'',item:k,size:e[k]||'',status,qty,issueDate:e[k+'IssueDate']||'',orderDate:e[k+'OrderDate']||'',replacementDue:e[k+'ReplacementDue']||'',cost:Number(e[k+'Cost']||0),notes:e[k+'Notes']||'',legacy:true});}for(const raw of equipmentList(e)){if(!isUniformItemType(raw&&raw.item))continue;let i={...raw};i.employee=fullName(e);i.employeeId=e.id;i.rank=e.rank||'';i.shift=e.shift||'';i.item=i.item||'Other';i.status=normalizedStatus(i.status||'issued');i.qty=Number(i.qty||1);i.cost=Number(i.cost||0);out.push(i);}return out;}
function getUniformItems(mode='all'){let emps=(roster.employees||[]).filter(e=>!isArchivedEmployee(e)&&!['ONIN','APS','Onin'].includes(e.type)&&!['ONIN','APS'].includes(e.rank));let items=[];for(const e of emps)items.push(...getUniformItemsForEmployee(e));if(mode&&mode!=='all')items=items.filter(i=>normalizedStatus(i.status)===normalizedStatus(mode));return items;}
function uniformStatusBadge(v){let st=normalizedStatus(v);return `<span class="status-badge ${esc(st)}">${esc(titleCase(st))}</span>`}
function equipmentStatusOptions(sel){return EQUIPMENT_STATUS.map(s=>`<option value="${esc(normalizedStatus(s))}" ${normalizedStatus(sel)===normalizedStatus(s)?'selected':''}>${esc(s)}</option>`).join('')}
function equipmentTypeOptions(sel){let set=new Set([...DEFAULT_EQUIPMENT_TYPES]);for(const e of roster.employees||[])for(const i of equipmentList(e))if(i.item&&isUniformItemType(i.item))set.add(i.item);return [...set].sort().map(s=>`<option value="${esc(s)}" ${String(sel||'')===s?'selected':''}>${esc(s)}</option>`).join('')}
function replacementDueClass(d){if(!d)return '';let due=new Date(d+'T00:00:00');if(isNaN(due))return '';let today=new Date();today.setHours(0,0,0,0);let diff=(due-today)/86400000;if(diff<0)return 'past-due';if(diff<=30)return 'due-soon';return '';}
function uniformMetrics(){const items=getUniformItems('all');const dueSoon=items.filter(i=>{let c=replacementDueClass(i.replacementDue);return c==='due-soon'||c==='past-due'});return{items,needed:items.filter(i=>i.status==='needed').length,ordered:items.filter(i=>i.status==='ordered').length,issued:items.filter(i=>i.status==='issued').length,returned:items.filter(i=>i.status==='returned').length,lostDamaged:items.filter(i=>['lost','damaged'].includes(i.status)).length,retired:items.filter(i=>i.status==='retired').length,dueSoon:dueSoon.length,value:items.filter(i=>['issued','lost','damaged'].includes(i.status)).reduce((n,i)=>n+(Number(i.cost||0)*Number(i.qty||1)),0)}}
function openEquipmentModal(empId,itemId=''){if(!canAdmin()){toast('Uniform edits are Admin-only');return;}let e=(roster.employees||[]).find(x=>String(x.id)===String(empId));if(!e){toast('Employee not found');return;}let list=equipmentList(e);let item=itemId?list.find(i=>String(i.id)===String(itemId)):null;item=item||{id:'',item:'Shirt',size:'',qty:1,status:'issued',issueDate:'',orderDate:'',replacementDue:'',cost:'',notes:''};showModal(`<div class="modal-head"><div class="modal-title">${item.id?'Edit':'Add'} Uniform Item</div><button onclick="closeModal()">Close</button></div><div class="notice">Employee: <strong>${esc(fullName(e))}</strong>. Use this for uniforms only. Radios, keys, office supplies, badges, and access cards are tracked in separate modules/tools.</div><div class="form-grid"><div><label>Item Type</label><select id="eqItem">${equipmentTypeOptions(item.item)}</select></div><div><label>Size</label><input id="eqSize" value="${esc(item.size||'')}" placeholder="XL, 2XL, 40x32, etc."></div><div><label>Quantity</label><input id="eqQty" type="number" min="1" value="${esc(item.qty||1)}"></div><div><label>Status</label><select id="eqStatus">${equipmentStatusOptions(item.status)}</select></div><div><label>Order Date</label><input id="eqOrderDate" type="date" value="${esc(item.orderDate||'')}"></div><div><label>Issue Date</label><input id="eqIssueDate" type="date" value="${esc(item.issueDate||'')}"></div><div><label>Replacement Due</label><input id="eqReplacementDue" type="date" value="${esc(item.replacementDue||'')}"></div><div><label>Cost</label><input id="eqCost" type="number" step="0.01" min="0" value="${esc(item.cost||'')}"></div><div class="full"><label>Notes</label><textarea id="eqNotes" rows="3">${esc(item.notes||'')}</textarea></div></div><div class="modal-actions"><button onclick="closeModal()">Cancel</button>${item.id?`<button class="danger" onclick="deleteEquipmentItem('${esc(e.id)}','${esc(item.id)}')">Delete</button>`:''}<button class="primary" onclick="saveEquipmentItem('${esc(e.id)}','${esc(item.id||'')}')">Save Uniform Item</button></div>`)}
async function saveEquipmentItem(empId,itemId=''){let e=(roster.employees||[]).find(x=>String(x.id)===String(empId));if(!e)return;let list=equipmentList(e);let item=itemId?list.find(i=>String(i.id)===String(itemId)):null;if(!item){item={id:'eq-'+Date.now()+'-'+Math.floor(Math.random()*1000)};list.push(item);}item.item=val('eqItem')||'Other';item.size=val('eqSize');item.qty=Number(val('eqQty')||1);item.status=normalizedStatus(val('eqStatus'));item.orderDate=val('eqOrderDate');item.issueDate=val('eqIssueDate');item.replacementDue=val('eqReplacementDue');item.cost=Number(val('eqCost')||0);item.notes=val('eqNotes');item.updatedAt=new Date().toISOString();item.updatedBy=currentUserName()||env.user||'';roster.audit=Array.isArray(roster.audit)?roster.audit:[];roster.audit.unshift({at:new Date().toISOString(),user:currentUserName()||env.user||'',action:'Uniform item saved',detail:`${fullName(e)} - ${item.item} (${titleCase(item.status)})`});await saveRosterNow('equipment-save');closeModal();safeRenderPages({preserveScroll:true});toast('Uniform item saved');}
async function deleteEquipmentItem(empId,itemId){let e=(roster.employees||[]).find(x=>String(x.id)===String(empId));if(!e)return;if(!confirm('Delete this uniform item?'))return;e.equipmentItems=equipmentList(e).filter(i=>String(i.id)!==String(itemId));roster.audit=Array.isArray(roster.audit)?roster.audit:[];roster.audit.unshift({at:new Date().toISOString(),user:currentUserName()||env.user||'',action:'Uniform item deleted',detail:fullName(e)});await saveRosterNow('equipment-delete');closeModal();safeRenderPages({preserveScroll:true});toast('Uniform item deleted');}
function openSeparationChecklist(empId){if(!canAdmin()){toast('Separation checklist is Admin-only');return;}let e=(roster.employees||[]).find(x=>String(x.id)===String(empId));if(!e)return;let c=e.separationChecklist||{};const chk=(k,label)=>`<label class="check-item"><input type="checkbox" id="sep_${k}" ${c[k]?'checked':''}> ${esc(label)}</label>`;showModal(`<div class="modal-head"><div class="modal-title">Separation / Return Checklist</div><button onclick="closeModal()">Close</button></div><div class="notice">Track returned company property for <strong>${esc(fullName(e))}</strong>. This is useful when an employee is archived or removed.</div><div class="separation-checklist">${chk('badge','Badge returned')}${chk('keys','Keys returned')}${chk('radio','Radio returned')}${chk('uniforms','Uniforms returned')}${chk('accessCard','Access card returned')}${chk('other','Other equipment returned')}</div><div class="form-grid"><div class="full"><label>Checklist Notes</label><textarea id="sep_notes" rows="3">${esc(c.notes||'')}</textarea></div></div><div class="modal-actions"><button onclick="closeModal()">Cancel</button><button class="primary" onclick="saveSeparationChecklist('${esc(e.id)}')">Save Checklist</button></div>`)}
async function saveSeparationChecklist(empId){let e=(roster.employees||[]).find(x=>String(x.id)===String(empId));if(!e)return;e.separationChecklist={badge:!!document.getElementById('sep_badge')?.checked,keys:!!document.getElementById('sep_keys')?.checked,radio:!!document.getElementById('sep_radio')?.checked,uniforms:!!document.getElementById('sep_uniforms')?.checked,accessCard:!!document.getElementById('sep_accessCard')?.checked,other:!!document.getElementById('sep_other')?.checked,notes:val('sep_notes'),updatedAt:new Date().toISOString(),updatedBy:currentUserName()||env.user||''};roster.audit=Array.isArray(roster.audit)?roster.audit:[];roster.audit.unshift({at:new Date().toISOString(),user:currentUserName()||env.user||'',action:'Separation checklist updated',detail:fullName(e)});await saveRosterNow('separation-checklist');closeModal();safeRenderPages({preserveScroll:true});toast('Separation checklist saved');}
function equipmentEmployeeOptions(){return rosterActiveEmployees().sort((a,b)=>fullName(a).localeCompare(fullName(b))).map(e=>`<option value="${esc(e.id)}">${esc(fullName(e))} - ${esc(e.shift||'')}</option>`).join('')}
function openQuickAddEquipmentModal(){if(!canAdmin()){toast('Uniform edits are Admin-only');return;}showModal(`<div class="modal-head"><div class="modal-title">Add Uniform Item</div><button onclick="closeModal()">Close</button></div><div class="notice">Uniforms only. Radios, keys, badges/access cards, and office supplies are intentionally excluded.</div><div class="form-grid"><div class="full"><label>Employee</label><select id="quickEqEmp">${equipmentEmployeeOptions()}</select></div></div><div class="modal-actions"><button onclick="closeModal()">Cancel</button><button class="primary" onclick="let id=val('quickEqEmp');closeModal();openEquipmentModal(id)">Continue</button></div>`)}
function uniformInlineId(empId,itemId,field){return 'uni_'+String(empId||'').replace(/[^a-zA-Z0-9_-]/g,'')+'_'+String(itemId||'new').replace(/[^a-zA-Z0-9_-]/g,'')+'_'+field}
function uniformInlineValue(empId,itemId,field){let el=document.getElementById(uniformInlineId(empId,itemId,field));return el?el.value:''}
function renderUniformEditableRow(emp,item){
  const itemId=item.legacy?('legacy-'+item.item):String(item.id||'');
  const typeCell=item.legacy?`<strong>${esc(titleCase(item.item))}</strong><div class="mini-note">Legacy roster field</div>`:`<select id="${uniformInlineId(emp.id,itemId,'item')}">${equipmentTypeOptions(item.item)}</select>`;
  return `<tr><td>${typeCell}</td><td><input id="${uniformInlineId(emp.id,itemId,'size')}" value="${esc(item.size||'')}" placeholder="Size"></td><td><input id="${uniformInlineId(emp.id,itemId,'qty')}" type="number" min="1" value="${esc(item.qty||1)}"></td><td><select id="${uniformInlineId(emp.id,itemId,'status')}">${equipmentStatusOptions(item.status)}</select></td><td><input id="${uniformInlineId(emp.id,itemId,'orderDate')}" type="date" value="${esc(item.orderDate||'')}"></td><td><input id="${uniformInlineId(emp.id,itemId,'issueDate')}" type="date" value="${esc(item.issueDate||'')}"></td><td><input id="${uniformInlineId(emp.id,itemId,'replacementDue')}" type="date" value="${esc(item.replacementDue||'')}" class="${esc(replacementDueClass(item.replacementDue))}"></td><td class="admin-pay"><input id="${uniformInlineId(emp.id,itemId,'cost')}" type="number" step="0.01" min="0" value="${esc(item.cost||'')}"></td><td><input id="${uniformInlineId(emp.id,itemId,'notes')}" value="${esc(item.notes||'')}" placeholder="Notes"></td><td><button class="sm primary admin-only" onclick="saveUniformInline('${esc(emp.id)}','${esc(itemId)}')">Save</button>${item.legacy?'':` <button class="sm danger admin-only" onclick="deleteEquipmentItem('${esc(emp.id)}','${esc(item.id)}')">Delete</button>`}</td></tr>`
}
async function saveUniformInline(empId,itemId){
  if(!canAdmin()){toast('Uniform edits are Admin-only');return;}
  let e=(roster.employees||[]).find(x=>String(x.id)===String(empId));if(!e){toast('Employee not found');return;}
  const legacy=String(itemId||'').startsWith('legacy-');
  const size=uniformInlineValue(empId,itemId,'size');
  const qty=Number(uniformInlineValue(empId,itemId,'qty')||1);
  const status=normalizedStatus(uniformInlineValue(empId,itemId,'status'));
  const orderDate=uniformInlineValue(empId,itemId,'orderDate');
  const issueDate=uniformInlineValue(empId,itemId,'issueDate');
  const replacementDue=uniformInlineValue(empId,itemId,'replacementDue');
  const cost=Number(uniformInlineValue(empId,itemId,'cost')||0);
  const notes=uniformInlineValue(empId,itemId,'notes');
  if(legacy){
    const key=String(itemId).replace('legacy-','');
    if(!['shirt','pants','jacket'].includes(key)){toast('Unknown legacy uniform item');return;}
    e[key]=size;e[key+'Status']=status;e[key+'OrderDate']=orderDate;e[key+'IssueDate']=issueDate;e[key+'ReplacementDue']=replacementDue;e[key+'Cost']=cost;e[key+'Notes']=notes;e[key+'Qty']=qty;
  }else{
    let list=equipmentList(e);let item=list.find(i=>String(i.id)===String(itemId));
    if(!item){toast('Uniform item not found');return;}
    item.item=uniformInlineValue(empId,itemId,'item')||item.item||'Other';item.size=size;item.qty=qty;item.status=status;item.orderDate=orderDate;item.issueDate=issueDate;item.replacementDue=replacementDue;item.cost=cost;item.notes=notes;item.updatedAt=new Date().toISOString();item.updatedBy=currentUserName()||env.user||'';
  }
  roster.audit=Array.isArray(roster.audit)?roster.audit:[];
  roster.audit.unshift({at:new Date().toISOString(),user:currentUserName()||env.user||'',action:'Uniform row saved',detail:fullName(e)});
  await saveRosterNow('uniform-inline-save');
  safeRenderPages({preserveScroll:true});toast('Uniform row saved');
}
async function markAllPantsNeeded(){
  if(!canAdmin()){toast('Uniform edits are Admin-only');return;}
  const emps=(roster.employees||[]).filter(e=>!isArchivedEmployee(e)&&!['ONIN','APS','Onin'].includes(e.type)&&!['ONIN','APS'].includes(e.rank));
  if(!emps.length){toast('No active Pig employees found for pants update');return;}
  if(!confirm('Mark pants as Needed for all active Pig employees? This keeps sizes and notes but changes the pants status for everyone in Uniform Accountability.'))return;
  let changed=0;
  for(const e of emps){
    if(normalizedStatus(e.pantsStatus)!=='needed'){changed++;}
    e.pantsStatus='needed';
  }
  roster.audit=Array.isArray(roster.audit)?roster.audit:[];
  roster.audit.unshift({at:new Date().toISOString(),user:currentUserName()||env.user||'',action:'Bulk uniform pants update',detail:`Marked pants Needed for ${emps.length} active Pig employee(s); ${changed} changed from another status.`});
  await saveRosterNow('uniform-pants-needed-bulk');
  safeRenderPages({preserveScroll:true});
  toast(`Pants marked Needed for ${emps.length} active employee(s)`);
}
function renderRosterUniforms(){
  const metrics=uniformMetrics();
  const items=metrics.items;
  const value=money(metrics.value)||'$0.00';
  const byStatus=['needed','ordered','issued','returned','lost','damaged','retired'].map(st=>({st,count:items.filter(i=>i.status===st).length}));
  const focus=String(window._uniformEmployeeFocus||'');
  const emps=(roster.employees||[]).filter(e=>!isArchivedEmployee(e)&&!['ONIN','APS','Onin'].includes(e.type)&&!['ONIN','APS'].includes(e.rank)).slice().sort((a,b)=>{
    if(focus&&String(a.id)===focus)return -1;if(focus&&String(b.id)===focus)return 1;
    return fullName(a).localeCompare(fullName(b),undefined,{numeric:true,sensitivity:'base'});
  });
  const grouped=emps.map(e=>{
    const empItems=getUniformItemsForEmployee(e).filter(i=>isUniformItemType(i.item));
    const open=empItems.filter(i=>!['issued','returned','retired'].includes(i.status)).length;
    const issued=empItems.filter(i=>i.status==='issued').length;
    const due=empItems.filter(i=>['due-soon','past-due'].includes(replacementDueClass(i.replacementDue))).length;
    const idSafe=String(e.id||'').replace(/[^a-zA-Z0-9_-]/g,'');
    return `<div class="card uniform-employee-card ${focus&&String(e.id)===focus?'uniform-focused':''}" id="uniformEmp_${idSafe}"><div class="uniform-employee-head"><div><div class="card-title">${esc(fullName(e))}</div><div class="page-sub">${esc(e.shift||'')} · ${esc(e.rank||'')} ${e.eid?'· EID '+esc(e.eid):''}</div></div><div class="uniform-employee-kpis"><span class="risk-chip ${open?'warn':'ok'}">Open ${open}</span><span class="risk-chip ok">Issued ${issued}</span><span class="risk-chip ${due?'bad':'ok'}">Due ${due}</span><button class="sm admin-only" onclick="openEquipmentModal('${esc(e.id)}')">+ Add Item</button><button class="sm" onclick="openEmployeeProfile('${esc(e.id)}')">Profile</button></div></div><div class="table-wrap"><table class="wide-table uniform-edit-table"><thead><tr><th>Item</th><th>Size</th><th>Qty</th><th>Status</th><th>Ordered</th><th>Issued</th><th>Replace Due</th><th class="admin-pay">Cost</th><th>Notes</th><th>Actions</th></tr></thead><tbody>${empItems.map(i=>renderUniformEditableRow(e,i)).join('')||'<tr><td colspan="10">No uniform rows found for this employee.</td></tr>'}</tbody></table></div></div>`;
  }).join('');
  return `<div class="uniform-original"><div class="uniform-toolbar"><div><div class="page-title">Uniform Accountability</div><div class="page-sub">Grouped by employee. Edit uniform rows directly in the table, then use Save on that row.</div></div><div class="top-actions"><button class="primary admin-only" onclick="openQuickAddEquipmentModal()">+ Add Uniform Item</button><button class="gold admin-only" onclick="markAllPantsNeeded()">Mark All Pants Needed</button><button onclick="openUniformPrintModal()">Print Uniforms</button><button onclick="exportUniformCSV()">Export CSV</button></div></div>${workflowBanner('Uniform workflow',['Review needed items','Order','Issue','Replace / retire'],'Uniforms should move through status intentionally. Bulk actions write audit entries.')}${renderPeopleWorkflowNav('uniforms')}<div class="stat-strip"><div class="stat-card"><div class="stat-value">${metrics.needed}</div><div class="stat-label">Needed</div></div><div class="stat-card orange"><div class="stat-value">${metrics.ordered}</div><div class="stat-label">Ordered</div></div><div class="stat-card blue"><div class="stat-value">${metrics.issued}</div><div class="stat-label">Issued</div></div><div class="stat-card"><div class="stat-value">${metrics.lostDamaged}</div><div class="stat-label">Lost / Damaged</div></div><div class="stat-card gold"><div class="stat-value">${metrics.dueSoon}</div><div class="stat-label">Replacement Due</div></div><div class="stat-card gold admin-pay"><div class="stat-value" style="font-size:20px">${value}</div><div class="stat-label">Uniform Value</div></div></div><div class="card"><div class="card-title">Status Breakdown</div><div class="uniform-status-grid">${byStatus.map(x=>`<div class="settings-kpi"><span>${esc(titleCase(x.st))}</span><strong>${x.count}</strong></div>`).join('')}</div></div><div class="notice">Uniforms only. Radios, keys, office supplies, badges/access cards, flashlights, and rain gear are intentionally excluded and should stay in their own trackers.</div>${grouped||'<div class="card"><p class="empty-note">No active employees available for uniform tracking.</p></div>'}</div>`
}

function renderRosterAnalytics(){
  const activeEmps=rosterActiveEmployees();
  const byShift=countBy(activeEmps,e=>e.shift||'Blank');
  const byRank=countBy(activeEmps,e=>e.rank||'Blank');
  const byClass=countBy(activeEmps,e=>employmentClass(e));
  const sched=scheduleMetrics();
  const coverage=scheduleAuthorityModel(sched);
  const costRows=employeeCostRows(activeEmps);
  const openUniform=uniformMetrics().needed+uniformMetrics().ordered+uniformMetrics().lostDamaged+uniformMetrics().dueSoon;
  const training=trainingReadinessMetrics(activeEmps);
  const tempPct=activeEmps.length?(((byClass.TempToHire||0)/activeEmps.length)*100):0;
  return `<div class="analytics-toolbar"><div><div class="page-title">Labor Analytics</div><div class="page-sub">Headcount, coverage, loaded cost, overtime exposure, RDO risk, temp dependency, and readiness indicators from the live roster schedule.</div></div><div class="top-actions"><button onclick="printAnalytics()">Print Analytics</button><button onclick="exportAnalyticsCSV()">Export Analytics CSV</button></div></div>${screenGuide('reports')}
  <div class="grid cols-4"><div class="kpi"><div class="num">${activeEmps.length}</div><div class="lbl">Active Employees</div></div><div class="kpi"><div class="num">${byClass.FT||0}</div><div class="lbl">FT Pig · ${loadedCostPercent('FT')}</div></div><div class="kpi"><div class="num">${byClass.PT||0}</div><div class="lbl">PT Pig · ${loadedCostPercent('PT')}</div></div><div class="kpi"><div class="num">${byClass.TempToHire||0}</div><div class="lbl">Temps · ${loadedCostPercent('TempToHire')}</div></div><div class="kpi"><div class="num">${sched.assignedHours}</div><div class="lbl">Assigned HPW</div></div><div class="kpi"><div class="num schedule-risk">${coverage.total.openHours}</div><div class="lbl">Open/Pending HPW Gap</div></div><div class="kpi"><div class="num schedule-risk">${sched.overtimeHours}</div><div class="lbl">OT Exposure HPW</div></div><div class="kpi"><div class="num">${money(sched.loadedCost)}</div><div class="lbl">Loaded Cost / Week</div></div></div>
  <div class="grid cols-2"><div class="card"><div class="card-title">Schedule Authority Coverage</div><div class="analytics-money">${coverage.total.openPosts} open post(s) · ${coverage.total.openHours} Open/Pending HPW</div><div class="health-row"><span>Required HPW</span><span>${coverage.total.requiredHours}</span></div><div class="health-row"><span>Named Scheduled HPW</span><span>${coverage.total.scheduledHours}</span></div><div class="health-row"><span>Highest-risk area</span><span class="warn">${esc(coverage.total.highestRisk)}</span></div><div class="health-row"><span>Est. loaded weekly gap cost</span><span>${money(estimatedLoadedGapCost(coverage))}</span></div></div><div class="card"><div class="card-title">PT / FT / TempToHire</div>${analyticsBars(byClass)}<div class="health-row"><span>Temp dependency</span><span class="${tempPct>25?'warn':'ok'}">${tempPct.toFixed(1)}%</span></div></div><div class="card"><div class="card-title">Coverage Risk by Shift / Area</div>${coverageRiskTable(sched)}</div><div class="card"><div class="card-title">Cost Snapshot</div><div class="analytics-money">${money(sched.loadedCost)} / week loaded</div><div class="health-row admin-pay"><span>Base labor cost</span><span>${money(sched.cost)}</span></div><div class="health-row admin-pay"><span>Loaded add-on</span><span>${money(sched.loadedCost-sched.cost)}</span></div><div class="health-row"><span>Monthly loaded run rate</span><span>${money(sched.loadedCost*Number(settings.monthlyMultiplier||4.333))}</span></div><div class="health-row"><span>Annual loaded run rate</span><span>${money(sched.loadedCost*Number(settings.annualMultiplier||52))}</span></div></div><div class="card"><div class="card-title">Readiness / Risk Signals</div><div class="health-row"><span>Uniform needs/orders</span><span class="warn">${openUniform}</span></div><div class="health-row"><span>Training no-record/overdue</span><span class="warn">${training.issueCount}</span></div><div class="health-row"><span>Unmatched schedule names</span><span class="warn">${sched.unmatched}</span></div><div class="health-row"><span>RDO conflict flags</span><span class="warn">${sched.rdoConflicts}</span></div><div class="health-row"><span>People over ${Number(settings.fteBaselineHours||40)} HPW</span><span class="warn">${sched.overtimePeople}</span></div></div></div>
  <div class="card"><div class="card-title">Schedule Authority Detail</div>${coverageRequirementTable(coverage)}</div>
  <div class="card"><div class="card-title">Schedule Row Coverage Detail</div><div class="table-wrap"><table class="wide-table"><thead><tr><th>Section</th><th>Rows</th><th>Assigned Slots</th><th>Open Slots</th><th>Assigned HPW</th><th>Required HPW</th><th>Gap HPW</th><th>Base Cost</th><th>Loaded Cost</th></tr></thead><tbody>${Object.values(sched.sections).map(x=>`<tr><td>${esc(x.section)}</td><td>${x.rows}</td><td>${x.assigned}</td><td class="schedule-risk">${x.open}</td><td>${x.assignedHours}</td><td>${x.requiredHours}</td><td class="schedule-risk">${x.openHours}</td><td>${money(x.cost)}</td><td>${money(x.loadedCost)}</td></tr>`).join('')}</tbody></table></div></div>
  <div class="card admin-pay"><div class="card-title">Employee Cost Detail</div><div class="mini-note">Weekly cost uses named schedule assignments only. Employees with no named schedule cells are not included in payroll cost math.</div><div class="table-wrap"><table class="wide-table"><thead><tr><th>Employee</th><th>Class</th><th>Rate</th><th>HPW</th><th>Base Week</th><th>Loaded Week</th><th>Base Month</th><th>Loaded Month</th><th>Base Year</th><th>Loaded Year</th></tr></thead><tbody>${costRows.map(r=>`<tr><td><strong>${esc(r.employee)}</strong><br><span class="mini-note">${esc(r.shift)} · ${esc(r.rank)}${r.source==='schedule only'?' · schedule only':''}</span></td><td>${esc(r.class)}</td><td>${money(r.rate)}</td><td>${r.hours}</td><td>${money(r.baseWeek)}</td><td>${money(r.loadedWeek)}</td><td>${money(r.baseMonth)}</td><td>${money(r.loadedMonth)}</td><td>${money(r.baseYear)}</td><td>${money(r.loadedYear)}</td></tr>`).join('')}</tbody></table></div></div>`
}

function coverageRequirements(){return (settings.coverageRequirements&&settings.coverageRequirements.length?settings.coverageRequirements:DEFAULT_COVERAGE_REQUIREMENTS).map(normalizeCoverageRequirement)}
function coverageDayArray(r){r=r||{};let days=Array.isArray(r.days)?r.days:(Array.isArray(r.Days)?r.Days:[]);days=days.map(String).filter(d=>DAYS.includes(d));if(!days.length){const dt=String(r.dayType||r.DayType||'All');days=dt==='Weekday'?['Mon','Tue','Wed','Thu','Fri']:(dt==='Weekend'?['Sun','Sat']:[...DAYS]);}return days}
function coverageDayLabel(r){const days=coverageDayArray(r);if(days.length===7)return 'Sun-Sat';if(days.join('|')==='Mon|Tue|Wed|Thu|Fri')return 'Mon-Fri';if(days.join('|')==='Sun|Sat')return 'Sat-Sun';return days.join(', ')}
function coverageDayCount(r){return coverageDayArray(r).length}
function coverageRequirementHours(r){return Number(r.requiredHeadcount||0)*Number(r.hoursPerPost||0)*coverageDayCount(r)}
function coverageAreaKey(v){return String(v||'').toLowerCase().replace(/[^a-z0-9]/g,'')}
function scheduleAreaMatches(section,req){const a=coverageAreaKey(section),r=coverageAreaKey(req.section||req.area);if(!r)return false;return a===r||a.includes(r)||r.includes(a)}
function schedulePostMatches(post,req){const r=coverageAreaKey(req.post||'');if(!r)return true;const p=coverageAreaKey(post||'');return p===r||p.includes(r)||r.includes(p)}
function coverageScheduledHoursFor(req,metrics){let assigned=0,open=0,cost=0,loadedCost=0,slots=0;const reqDays=new Set(coverageDayArray(req));for(const row of (roster.schedule||[])){if(!scheduleAreaMatches(row.section,req)||!schedulePostMatches(row.post,req))continue;for(let dayIdx=0;dayIdx<(row.days||[]).length;dayIdx++){if(!reqDays.has(DAYS[dayIdx]))continue;let val=(row.days||[])[dayIdx];if(scheduleCellIsBlank(val))continue;let hrs=Number(row.hrs||req.hoursPerPost||8);if(scheduleCellIsOpen(val)){open+=hrs;continue;}assigned+=hrs;slots++;let emp=findRosterByScheduleName(val);if(emp){cost+=Number(emp.rate||0)*hrs;loadedCost+=loadedHourlyRate(emp)*hrs;}}}const required=coverageRequirementHours(req);return{assigned:Math.min(assigned,required),rawAssigned:assigned,open,cost,loadedCost,slots}}
function coverageRequirementModel(metrics=scheduleMetrics()){const rows=coverageRequirements().map(r=>{const reqH=coverageRequirementHours(r);const sched=coverageScheduledHoursFor(r,metrics);const gap=Math.max(0,reqH-sched.assigned);const over=Math.max(0,(sched.rawAssigned||sched.assigned)-reqH);let risk='Covered';if(reqH>0&&(sched.rawAssigned||sched.assigned)<=0)risk='No coverage';else if(gap>0)risk='Short';else if(over>0)risk='Overstaffed';if(risk==='Covered'&&sched.slots===1&&reqH>0)risk='Single point';return{...r,dayLabel:coverageDayLabel(r),requiredHours:reqH,scheduledHours:sched.assigned,rawScheduledHours:sched.rawAssigned||sched.assigned,openHours:gap,overHours:over,scheduledSlots:sched.slots,baseCost:sched.cost,loadedCost:sched.loadedCost,risk}});const total=rows.reduce((o,r)=>{o.requiredHours+=r.requiredHours;o.scheduledHours+=r.scheduledHours;o.openHours+=r.openHours;o.overHours+=r.overHours;o.loadedCost+=r.loadedCost;o.openPosts+=Math.ceil(r.openHours/Math.max(1,Number(r.hoursPerPost||8)));return o},{requiredHours:0,scheduledHours:0,openHours:0,overHours:0,loadedCost:0,openPosts:0});total.highestRisk=(rows.slice().sort((a,b)=>b.openHours-a.openHours)[0]||{}).area||'None';return{rows,total}}
function coverageRequirementTable(model){const rows=(model&&model.rows)||[];if(!rows.length)return '<p class="empty-note">No required coverage rules configured.</p>';return `<div class="table-wrap"><table class="wide-table"><thead><tr><th>Area</th><th>Section</th><th>Post</th><th>Days</th><th>Req HC</th><th>Hours/Post</th><th>Required HPW</th><th>Named Scheduled HPW</th><th>Gap HPW</th><th>Risk</th><th>Notes</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.area)}</td><td>${esc(r.section)}</td><td>${esc(r.post||'All')}</td><td>${esc(r.dayLabel||coverageDayLabel(r))}</td><td>${r.requiredHeadcount}</td><td>${r.hoursPerPost}</td><td>${r.requiredHours}</td><td>${r.scheduledHours}</td><td class="schedule-risk">${r.openHours}</td><td><span class="risk-chip ${r.risk==='Covered'?'ok':r.risk==='Overstaffed'?'warn':'bad'}">${esc(r.risk)}</span></td><td class="notes-cell">${esc(r.notes)}</td></tr>`).join('')}</tbody></table></div>`}
function estimatedLoadedGapCost(model){const rows=(model&&model.rows)||[];let avgLoaded=0,count=0;for(const r of rows){if(r.scheduledHours>0&&r.loadedCost>0){avgLoaded+=r.loadedCost/r.scheduledHours;count++;}}const hourly=count?avgLoaded/count:loadedHourlyRate({rate:18,employmentClass:'FT'});return (model.total.openHours||0)*hourly}
function scheduleMetrics(rowsOverride=null){let out={hours:0,assignedHours:0,requiredHours:0,openHours:0,cost:0,loadedCost:0,open:0,unmatched:0,fte:0,rdoConflicts:0,overtimeHours:0,overtimePeople:0,sections:{},risk:{},employeeHours:{}};const metricRows=Array.isArray(rowsOverride)?rowsOverride:(roster.schedule||[]);for(const row of metricRows){let sec=row.section||'Unassigned';let shift=scheduleSectionShift(sec);let bucket=out.sections[sec]||(out.sections[sec]={section:sec,rows:0,assigned:0,open:0,assignedHours:0,requiredHours:0,openHours:0,cost:0,loadedCost:0});let risk=out.risk[shift]||(out.risk[shift]={shift,assigned:0,open:0,assignedHours:0,requiredHours:0,openHours:0});bucket.rows++;for(let dayIdx=0;dayIdx<(row.days||[]).length;dayIdx++){let val=(row.days||[])[dayIdx];let low=String(val||'').trim().toLowerCase();if(scheduleCellIsBlank(val))continue;let hrs=Number(row.hrs||8);bucket.requiredHours+=hrs;out.requiredHours+=hrs;risk.requiredHours+=hrs;if(scheduleCellIsOpen(val)){out.open++;out.openHours+=hrs;bucket.open++;bucket.openHours+=hrs;risk.open++;risk.openHours+=hrs;continue;}out.hours+=hrs;out.assignedHours+=hrs;bucket.assigned++;bucket.assignedHours+=hrs;risk.assigned++;risk.assignedHours+=hrs;let emp=findRosterByScheduleName(val);if(emp){let cost=Number(emp.rate||0)*hrs;let loaded=loadedHourlyRate(emp)*hrs;out.cost+=cost;out.loadedCost+=loaded;bucket.cost+=cost;bucket.loadedCost+=loaded;let key=String(emp.id);out.employeeHours[key]=(out.employeeHours[key]||0)+hrs;if((emp.rdo||[]).includes(DAYS[dayIdx]))out.rdoConflicts++;}else out.unmatched++;}}for(const [id,h] of Object.entries(out.employeeHours)){const fteBase=Number(settings.fteBaselineHours||40);if(h>fteBase){out.overtimePeople++;out.overtimeHours+=h-fteBase;}}out.fte=out.assignedHours/Number(settings.fteBaselineHours||40);return out}
function coverageRiskTable(sched){let rows=Object.values(sched.risk||{}).sort((a,b)=>b.openHours-a.openHours||String(a.shift).localeCompare(String(b.shift)));if(!rows.length)return '<p class="empty-note">No schedule rows found.</p>';return `<div class="table-wrap"><table class="wide-table"><thead><tr><th>Shift / Area</th><th>Assigned HPW</th><th>Required HPW</th><th>Gap HPW</th><th>Open Slots</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.shift)}</td><td>${r.assignedHours}</td><td>${r.requiredHours}</td><td class="schedule-risk">${r.openHours}</td><td class="schedule-risk">${r.open}</td></tr>`).join('')}</tbody></table></div>`}
function trainingReadinessMetrics(activeEmps){let issueCount=0,missing=0,expired=0,expiring=0,current=0,totalRequired=0;for(const e of activeEmps||[]){const r=trainingReadinessForEmployee(e);missing+=r.missing;expired+=r.expired;expiring+=r.expiring;current+=r.current;totalRequired+=r.total;issueCount+=r.missing+r.expired;}const score=totalRequired?Math.round((current/totalRequired)*100):100;return{issueCount,missing,expired,expiring,current,totalRequired,score}}
function exportAnalyticsCSV(){if(!canViewLaborSummary()){toast('Labor analytics export is restricted');return;}let m=scheduleMetrics();const active=rosterActiveEmployees(), classes=employmentClassCounts(active);let costRows=employeeCostRows(active);let coverage=coverageRequirementModel(m);let rows=[['Metric','Value'],['Active Employees',active.length],['FT Pig Employees',classes.FT||0],['PT Pig Employees',classes.PT||0],['TempToHire Employees',classes.TempToHire||0],['FT Loaded Rate',loadedCostPercent('FT')],['PT Loaded Rate',loadedCostPercent('PT')],['Temp Loaded Rate',loadedCostPercent('TempToHire')],['Assigned HPW',m.assignedHours],['Required HPW',m.requiredHours],['Open/Pending HPW Gap',coverage.total.openHours],['FTE',m.fte.toFixed(2)],['Coverage Open Posts',coverage.total.openPosts],['People Over FTE Baseline',m.overtimePeople],['OT Exposure HPW',m.overtimeHours],['RDO Conflict Flags',m.rdoConflicts],['Loaded Weekly Cost',m.loadedCost.toFixed(2)],['Loaded Monthly Run Rate',(m.loadedCost*Number(settings.monthlyMultiplier||4.333)).toFixed(2)],['Loaded Annual Run Rate',(m.loadedCost*Number(settings.annualMultiplier||52)).toFixed(2)]];if(canViewIndividualPay()){rows.push(['Base Weekly Cost',m.cost.toFixed(2)],['Loaded Add-On',(m.loadedCost-m.cost).toFixed(2)]);}rows.push([],['Coverage Area','Section','Post','Days','Required HC','Hours/Post','Required HPW','Named Scheduled HPW','Gap HPW','Risk','Notes'],...coverage.rows.map(r=>[r.area,r.section,r.post||'',r.dayLabel||coverageDayLabel(r),r.requiredHeadcount,r.hoursPerPost,r.requiredHours,r.scheduledHours,r.openHours,r.risk,r.notes]),[],['Section','Rows','Assigned Slots','Open Slots','Assigned HPW','Required HPW','Gap HPW'].concat(canViewIndividualPay()?['Base Cost','Loaded Cost']:['Loaded Cost']),...Object.values(m.sections).map(x=>[x.section,x.rows,x.assigned,x.open,x.assignedHours,x.requiredHours,x.openHours].concat(canViewIndividualPay()?[x.cost.toFixed(2),x.loadedCost.toFixed(2)]:[x.loadedCost.toFixed(2)])));if(canViewIndividualPay()){rows.push([],['Employee','EID','Shift','Rank','Class','Rate','HPW','Hour Source','Base Week','Loaded Week','Base Month','Loaded Month','Base Year','Loaded Year'],...costRows.map(r=>[r.employee,r.eid,r.shift,r.rank,r.class,r.rate.toFixed(2),r.hours,r.source,r.baseWeek.toFixed(2),r.loadedWeek.toFixed(2),r.baseMonth.toFixed(2),r.loadedMonth.toFixed(2),r.baseYear.toFixed(2),r.loadedYear.toFixed(2)]));}downloadCSV('PWADC_Roster_Analytics_'+new Date().toISOString().slice(0,10)+'.csv',rows)}

function printAnalytics(){
  let m=scheduleMetrics();
  let rows=Object.values(m.sections);
  let coverage=coverageRequirementModel(m);
  let costRows=employeeCostRows(rosterActiveEmployees());
  let employeeSection=canViewIndividualPay()?`<h3>Employee Cost Detail</h3><table class="print-table"><thead><tr><th>Employee</th><th>Class</th><th>HPW</th><th>Base Week</th><th>Loaded Week</th><th>Base Month</th><th>Loaded Month</th><th>Base Year</th><th>Loaded Year</th></tr></thead><tbody>${costRows.map(r=>`<tr><td>${esc(r.employee)}</td><td>${esc(r.class)}</td><td>${r.hours}</td><td>${money(r.baseWeek)}</td><td>${money(r.loadedWeek)}</td><td>${money(r.baseMonth)}</td><td>${money(r.loadedMonth)}</td><td>${money(r.baseYear)}</td><td>${money(r.loadedYear)}</td></tr>`).join('')}</tbody></table>`:'';
  let html=`<div class="print-overlay" id="printOverlay"><div class="print-toolbar"><div><h2>PWADC Security Labor Analytics</h2><div>${new Date().toLocaleString()} · Required HPW ${coverage.total.requiredHours} · Named Scheduled HPW ${coverage.total.scheduledHours} · Open/Pending HPW ${coverage.total.openHours}</div></div><div><button onclick="window.print()">Print</button> <button onclick="document.getElementById('printOverlay').remove()">Close</button></div></div><h3>Required Coverage Model</h3><table class="print-table"><thead><tr><th>Area</th><th>Post</th><th>Days</th><th>Req HC</th><th>Required HPW</th><th>Named Scheduled HPW</th><th>Gap HPW</th><th>Risk</th></tr></thead><tbody>${coverage.rows.map(r=>`<tr><td>${esc(r.area)}</td><td>${esc(r.post||'All')}</td><td>${esc(r.dayLabel||coverageDayLabel(r))}</td><td>${r.requiredHeadcount}</td><td>${r.requiredHours}</td><td>${r.scheduledHours}</td><td>${r.openHours}</td><td>${esc(r.risk)}</td></tr>`).join('')}</tbody></table><h3>Schedule Row Coverage Detail</h3><table class="print-table"><thead><tr><th>Section</th><th>Assigned</th><th>Open</th><th>Assigned HPW</th><th>Required HPW</th><th>Gap HPW</th><th>Base Cost</th><th>Loaded Cost</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.section)}</td><td>${x.assigned}</td><td>${x.open}</td><td>${x.assignedHours}</td><td>${x.requiredHours}</td><td>${x.openHours}</td><td>${money(x.cost)}</td><td>${money(x.loadedCost)}</td></tr>`).join('')}</tbody></table>${employeeSection}</div>`;
  document.body.insertAdjacentHTML('beforeend',html);
  setTimeout(()=>window.print(),150);
}

function findRosterByScheduleName(raw){
  const cleaned=schedulePersonName(raw);
  if(!cleaned)return null;
  const p=attendanceNameParts(cleaned);
  const sl=normalizeNameKey(p.last), sf=normalizeNameKey(p.first);
  return (roster.employees||[]).find(e=>{
    const rp=attendanceNameParts(rosterEmployeeAttendanceName(e));
    const rl=normalizeNameKey(rp.last), rf=normalizeNameKey(rp.first);
    return rl&&sl&&rl===sl&&firstNameCompatible(rf,sf);
  })||null;
}
function isRosterArchived(e){
  return isArchivedEmployee(e);
}
function analyticsBars(obj){let entries=Object.entries(obj).sort((a,b)=>b[1]-a[1]);let max=Math.max(1,...entries.map(x=>x[1]));return `<div class="analytics-list">${entries.map(([k,v])=>`<div class="analytics-bar"><span>${esc(k)}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.round(v/max*100)}%"></div></div><strong>${v}</strong></div>`).join('')}</div>`}
function uniformPrintColumns(){return ['Employee','Rank','Shift','Item','Size/ID','Status','Qty','Ordered','Issued','Replace Due','Cost','Notes']}
function openUniformPrintModal(){
  const items=getUniformItems('all');
  const statuses=['needed','ordered','issued','returned','lost','damaged','retired'];
  const itemTypes=[...new Set(items.map(i=>String(i.item||'Other')).filter(Boolean))].sort((a,b)=>titleCase(a).localeCompare(titleCase(b)));
  const cols=uniformPrintColumns();
  showModal(`<div class="modal-head"><div class="modal-title">Print Uniforms</div><button onclick="closeModal()">Close</button></div><div class="notice">Choose exactly what needs to go on the uniform printout. This will go straight to the normal Windows print dialog without showing the full-screen print page first.</div><div class="form-grid"><div class="full"><label>Quick Scope</label><select id="upScope" onchange="applyUniformPrintScopePreset(this.value)"><option value="all">All uniform rows</option><option value="open">Open items only: needed, ordered, lost, damaged</option><option value="issued">Issued items only</option><option value="replacement">Replacement due / past due only</option></select></div><div class="full"><label>Status</label><div class="day-grid">${statuses.map(st=>`<label class="day-check"><input type="checkbox" class="upStatus" value="${esc(st)}" checked> ${esc(titleCase(st))}</label>`).join('')}</div></div><div class="full"><label>Item Type</label><div class="day-grid">${itemTypes.map(it=>`<label class="day-check"><input type="checkbox" class="upItem" value="${esc(it)}" checked> ${esc(titleCase(it))}</label>`).join('')||'<div class="mini-note">No uniform item types found.</div>'}</div></div><div class="full"><label>Columns</label><div class="day-grid">${cols.map(c=>`<label class="day-check"><input type="checkbox" class="upCol" value="${esc(c)}" checked> ${esc(c)}</label>`).join('')}</div></div><label class="day-check full"><input type="checkbox" id="upGroup" checked> Group by status</label></div><div class="modal-actions"><button onclick="setUniformPrintBasic()">Basic Columns</button><button onclick="document.querySelectorAll('.upCol,.upStatus,.upItem').forEach(x=>x.checked=true)">Select All</button><button onclick="closeModal()">Cancel</button><button class="primary" onclick="printUniformCustom()">Print</button></div>`);
}
function applyUniformPrintScopePreset(scope){
  const set=(cls,fn)=>document.querySelectorAll(cls).forEach(x=>x.checked=fn(x.value));
  if(scope==='open')set('.upStatus',v=>['needed','ordered','lost','damaged'].includes(v));
  else if(scope==='issued')set('.upStatus',v=>v==='issued');
  else set('.upStatus',()=>true);
}
function setUniformPrintBasic(){const basic=['Employee','Rank','Shift','Item','Size/ID','Status','Qty','Issued','Replace Due','Notes'];document.querySelectorAll('.upCol').forEach(x=>x.checked=basic.includes(x.value));}
function uniformPrintCell(i,c){return {'Employee':i.employee,'Rank':i.rank,'Shift':i.shift,'Item':titleCase(i.item),'Size/ID':i.size,'Status':titleCase(i.status),'Qty':i.qty,'Ordered':fmtDate(i.orderDate||''),'Issued':fmtDate(i.issueDate||''),'Replace Due':fmtDate(i.replacementDue||''),'Cost':money(i.cost||0),'Notes':i.notes}[c]??''}
function printUniformCustom(){
  let statuses=[...document.querySelectorAll('.upStatus:checked')].map(x=>x.value);
  let itemTypes=[...document.querySelectorAll('.upItem:checked')].map(x=>x.value);
  let cols=[...document.querySelectorAll('.upCol:checked')].map(x=>x.value);
  let scope=val('upScope');
  if(!statuses.length){toast('Choose at least one uniform status');return;}
  if(!itemTypes.length){toast('Choose at least one uniform item type');return;}
  if(!cols.length){toast('Choose at least one uniform column');return;}
  let items=getUniformItems('all').filter(i=>statuses.includes(String(i.status||''))&&itemTypes.includes(String(i.item||'')));
  if(scope==='replacement')items=items.filter(i=>['due-soon','past-due'].includes(replacementDueClass(i.replacementDue)));
  items=items.slice().sort((a,b)=>String(a.status||'').localeCompare(String(b.status||''))||String(a.employee||'').localeCompare(String(b.employee||''))||String(a.item||'').localeCompare(String(b.item||'')));
  const grouped=!!document.getElementById('upGroup')?.checked;
  let rows='';
  if(grouped){
    for(const st of ['needed','ordered','issued','returned','lost','damaged','retired']){
      const part=items.filter(i=>i.status===st);
      if(!part.length)continue;
      rows+=`<tr class="group-row"><th colspan="${cols.length}">${esc(titleCase(st))}</th></tr>`+part.map(i=>`<tr>${cols.map(c=>`<td>${esc(uniformPrintCell(i,c))}</td>`).join('')}</tr>`).join('');
    }
  }else rows=items.map(i=>`<tr>${cols.map(c=>`<td>${esc(uniformPrintCell(i,c))}</td>`).join('')}</tr>`).join('');
  let body=`<div class="print-header"><div><div class="print-brand">PWADC Security Operations Suite</div><h1>PWADC Security Uniform Accountability</h1><div class="print-note">${items.length} uniform row(s) · scope: ${esc(scope||'all')}</div></div><div class="print-meta">Generated ${esc(new Date().toLocaleString())}<br>Version v3.3.1.0</div></div><table><thead><tr>${cols.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${cols.length}">No uniform rows match the selected print options.</td></tr>`}</tbody></table>`;
  closeModal();printHtmlDirect('PWADC Security Uniform Accountability',body,cols.length>8?'landscape':'portrait');
}
function printUniformOrderSheet(){openUniformPrintModal()}
function exportUniformCSV(){let rows=[['Employee','Rank','Shift','Item','Size/ID','Status','Qty','Order Date','Issue Date','Replacement Due','Cost','Notes'],...getUniformItems('all').map(i=>[i.employee,i.rank,i.shift,titleCase(i.item),i.size,i.status,i.qty,i.orderDate||'',i.issueDate||'',i.replacementDue||'',i.cost||'',i.notes||''])];downloadCSV('PWADC_Uniforms_'+new Date().toISOString().slice(0,10)+'.csv',rows)}
function downloadCSV(name,rows){let csv=rows.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\n');let blob=new Blob([csv],{type:'text/csv'});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}

function countBy(arr,fn){let o={};for(const x of arr){let k=fn(x);o[k]=(o[k]||0)+1}return o}
function val(id){let el=document.getElementById(id);return el?el.value:''}
function showModal(html){
  closeModal();
  let d=document.createElement('div');
  d.className='modal-backdrop';d.id='modalBackdrop';
  d.innerHTML='<div class="modal-card">'+html+'</div>';
  d.addEventListener('click',ev=>{if(ev.target===d)closeModal();});
  const card=d.querySelector('.modal-card');
  if(card)card.addEventListener('click',ev=>ev.stopPropagation());
  document.body.appendChild(d);
  setTimeout(()=>{let f=d.querySelector('input,select,textarea,button');if(f&&f.focus)f.focus();},30);
}
function closeModal(){let d=document.getElementById('modalBackdrop');if(d)d.remove()}
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.getElementById('modalBackdrop'))closeModal();});
async function importRosterJSON(input){const file=input&&input.files&&input.files[0];if(!file)return;try{const text=await file.text();const data=JSON.parse(text);if(!Array.isArray(data.employees)||!Array.isArray(data.schedule))throw new Error('File does not look like a PWADC roster/staff JSON export.');roster=data;normalizeRoster();roster.audit.push({at:new Date().toISOString(),user:currentUserName()||env.user||'',action:'Roster JSON imported',detail:file.name});await createRosterBackup();await saveRosterNow('import');await syncAttendanceFromRoster(false);safeRenderPages();toast('Imported roster JSON and synced Attendance: '+file.name)}catch(e){toast('Roster import failed: '+e.message)}finally{if(input)input.value=''}}
async function reloadPackagedRosterData(){if(!confirm('Replace current shared roster data with the packaged recovery roster JSON? A backup will be created first.'))return;try{await createRosterBackup();let r=await SuiteBridge.send('suite:resetModuleFromSeed',{}, {module:'roster'});let raw=r.data;roster=typeof raw==='string'?JSON.parse(raw||'{}'):(raw||{});normalizeRoster();safeRenderPages();toast('Loaded packaged recovery roster JSON')}catch(e){toast('Roster reload failed: '+e.message)}}
async function createRosterBackup(){try{await SuiteBridge.send('suite:createBackup',roster,{module:'roster'});toast('Roster backup created')}catch(e){toast('Roster backup failed: '+e.message)}}
function exportRosterCSV(){let admin=canViewIndividualPay();let cols=admin?['Last','First','EID','Rank','Shift','Gate Shift','Rate','Type','PT/FT/Temp','DOH','DOP','RDO','Shirt','Shirt Status','Pants','Pants Status','Jacket','Jacket Status','Notes']:['Last','First','EID','Rank','Shift','Gate Shift','Type','PT/FT/Temp','DOH','DOP','RDO','Shirt','Shirt Status','Pants','Pants Status','Jacket','Jacket Status','Notes'];let rows=[cols.join(',')];for(const e of roster.employees){let vals=admin?[e.last,e.first,e.eid,e.rank,e.shift,e.gateShift,e.rate,e.type,employmentClass(e),e.doh,e.dop,(e.rdo||[]).join('/'),e.shirt,e.shirtStatus,e.pants,e.pantsStatus,e.jacket,e.jacketStatus,e.notes]:[e.last,e.first,e.eid,e.rank,e.shift,e.gateShift,e.type,employmentClass(e),e.doh,e.dop,(e.rdo||[]).join('/'),e.shirt,e.shirtStatus,e.pants,e.pantsStatus,e.jacket,e.jacketStatus,e.notes];rows.push(vals.map(x=>'"'+String(x||'').replace(/"/g,'""')+'"').join(','))}SuiteBridge.send('suite:writeExport',rows.join('\n'),{module:'roster',fileName:'roster-export-'+new Date().toISOString().slice(0,10)+'.csv'}).then(()=>toast(admin?'Roster CSV exported':'Roster CSV exported without pay-rate columns')).catch(e=>toast('Roster export failed: '+e.message))}
